"""Employee persistence model."""

import uuid
from datetime import date, datetime
from decimal import Decimal

from sqlalchemy import CheckConstraint, DateTime, Index, Numeric, String, func, text
from sqlalchemy.orm import Mapped, mapped_column

from acme_pay.core.database import Base, string_enum
from acme_pay.domain.employment import EmploymentStatus
from acme_pay.domain.money import Money

# Human-friendly, sequential IDs (EMP-000001) generated by the database, so they are
# unique even under concurrent inserts.
EMPLOYEE_CODE_DEFAULT = text("'EMP-' || lpad(nextval('employee_code_seq')::text, 6, '0')")


class Employee(Base):
    """A person employed by ACME, with their current annual base salary."""

    __tablename__ = "employees"
    # Fetch database-generated values (employee_code, timestamps) via RETURNING.
    __mapper_args__ = {"eager_defaults": True}  # noqa: RUF012 - SQLAlchemy declarative API
    __table_args__ = (
        CheckConstraint("salary > 0", name="ck_employees_salary_positive"),
        Index("ix_employees_country_job_title", "country_code", "job_title"),
        Index("ix_employees_department", "department"),
        Index("ix_employees_status", "status"),
    )

    id: Mapped[uuid.UUID] = mapped_column(primary_key=True, default=uuid.uuid4)
    employee_code: Mapped[str] = mapped_column(
        String(16), unique=True, server_default=EMPLOYEE_CODE_DEFAULT
    )
    first_name: Mapped[str] = mapped_column(String(100))
    last_name: Mapped[str] = mapped_column(String(100))
    email: Mapped[str] = mapped_column(String(254), unique=True)
    job_title: Mapped[str] = mapped_column(String(100))
    department: Mapped[str] = mapped_column(String(100))
    country_code: Mapped[str] = mapped_column(String(2))
    currency: Mapped[str] = mapped_column(String(3))
    salary: Mapped[Decimal] = mapped_column(Numeric(14, 2))
    hire_date: Mapped[date]
    status: Mapped[EmploymentStatus] = mapped_column(
        string_enum(EmploymentStatus, length=20), default=EmploymentStatus.ACTIVE
    )
    terminated_on: Mapped[date | None]
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), server_default=func.now())
    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), server_default=func.now(), onupdate=func.now()
    )

    @property
    def current_salary(self) -> Money:
        """The current salary as a Money value."""
        return Money(self.salary, self.currency)
